      caveman: { html: '<p><b>E1</b> starts as SN1: halide leaves slowly: carbocation. Weak solvent base takes β H: more substituted alkene (Zaitsev). No strong base, no anti rule. Rate = k[RX]. Shares cation with SN1.</p>' },
      id: 's23', type: 'explain', skill: 'e1',
