        mo('CCC[C@@H](C)Cl', '(R)-2-chloropentane', false, 'The halogen that replaces the OH is the one in the reagent. PBr₃ gives a bromide; a chloride would need SOCl₂.', { chk: { call: 'alcohol', args: ['CCC[C@H](C)O', 'PBr3'], kind: 'wrongHalogen' } })
